        : L('Payment Pending', 'చెల్లింపు పెండింగ్')
  return o.payment_method
}

// Fulfilment milestones — mirrors the consumer's tracker exactly so both
// sides stay in sync: Order placed → (Payment received) → Approved → Shipped
